def split_fields(line):
    import re
    def escape_double_quote(match):
        return match.group(1)
    result = re.split(r'(?<!")"(?:"")*(?=")', line)
    for i, field in enumerate(result):
        field = re.sub(r'"', '', field)
        field = re.sub(r'(?<!")"(?:"")*(?=")', escape_double_quote, field)
        result[i] = field
    return result
